const item = $input.first().json;

function uniq(arr) {
  return [...new Set((arr || []).map(x => String(x || '').trim()).filter(Boolean))];
}
function splitList(v) {
  if (Array.isArray(v)) return uniq(v);
  return uniq(String(v || '').split(/[;\n]/));
}

const subjectType = String(item.subjectType || 'attorney').toLowerCase() === 'business' ? 'business' : 'attorney';
const subject = item.subjectName;
const org = item.organizationName;
const category = item.category;
const market = item.cityState;
const analysisMonths = item.analysisMonths || 24;
const gbName = item.googleBusinessName || '';

// Keyword appended to name searches: 'attorney' for legal, category term for business
const keyword = subjectType === 'attorney' ? 'attorney' : (category || 'business');

// Calculate date range for news filtering
const endDate = new Date();
const startDate = new Date();
startDate.setMonth(startDate.getMonth() - analysisMonths);

// Default domain sets by subject type (used when caller provides none)
const DEFAULT_DOMAINS = subjectType === 'attorney'
  ? ['avvo','martindale','justia','findlaw','lawyersdotcom','superlawyers','gmb','yelp','bbb','linkedin','facebook','x','youtube','google_news']
  : ['gmb','yelp','bbb','trustpilot','glassdoor','angi','thumbtack','chamber','linkedin','facebook','x','youtube','google_news'];

const domainsIn = splitList(item.domains);
const selected = new Set(domainsIn.length ? domainsIn : DEFAULT_DOMAINS);

const queries = [];

// === SERP VISIBILITY QUERIES (multiple pages) ===
queries.push({ engine: 'google', q: `"${subject}" ${keyword}${market ? ' ' + market : ''}`, kind: 'serp_name_google_p1', num: 20, start: 0 });
queries.push({ engine: 'google', q: `"${subject}" ${keyword}${market ? ' ' + market : ''}`, kind: 'serp_name_google_p2', num: 20, start: 20 });
queries.push({ engine: 'bing', q: `"${subject}" ${keyword}${market ? ' ' + market : ''}`, kind: 'serp_name_bing', num: 30 });

if (selected.has('duckduckgo')) {
  queries.push({ engine: 'duckduckgo', q: `"${subject}" ${keyword}${market ? ' ' + market : ''}`, kind: 'serp_name_ddg' });
}

// === ALIAS SEARCHES (former firms, DBAs, name variants) ===
splitList(item.aliases).slice(0, 3).forEach((a, i) => {
  queries.push({ engine: 'google', q: `"${a}"${market ? ' ' + market : ''}`, kind: `serp_alias_${i + 1}`, num: 10 });
});

// === ORGANIZATION SEARCHES ===
if (org) {
  queries.push({ engine: 'google', q: `"${org}"${market ? ' ' + market : ''}`, kind: 'serp_org_google', num: 20 });
  queries.push({ engine: 'bing', q: `"${org}"${market ? ' ' + market : ''}`, kind: 'serp_org_bing', num: 20 });
}

// === CATEGORY + MARKET KEYWORD RANKINGS ===
if (category && market) {
  if (subjectType === 'attorney') {
    queries.push({ engine: 'google', q: `${category} lawyer ${market}`, kind: 'serp_category_google', num: 50 });
    queries.push({ engine: 'google', q: `${category} attorney ${market}`, kind: 'serp_category_alt_google', num: 50 });
    queries.push({ engine: 'google', q: `best ${category} lawyer ${market}`, kind: 'serp_best_category_google', num: 30 });
  } else {
    queries.push({ engine: 'google', q: `${category} ${market}`, kind: 'serp_category_google', num: 50 });
    queries.push({ engine: 'google', q: `best ${category} ${market}`, kind: 'serp_best_category_google', num: 30 });
    queries.push({ engine: 'google', q: `top ${category} ${market}`, kind: 'serp_category_alt_google', num: 30 });
  }
}

// === DIRECTORY SITE SEARCHES ===
function addSite(domainKey, site, label) {
  if (!selected.has(domainKey)) return;
  queries.push({
    engine: 'google',
    q: `site:${site} "${subject}"${market ? ' ' + market : ''}`,
    kind: `site_${label}`,
    num: 10
  });
}

if (subjectType === 'attorney') {
  addSite('avvo', 'avvo.com', 'avvo');
  addSite('martindale', 'martindale.com', 'martindale');
  addSite('justia', 'lawyers.justia.com', 'justia');
  addSite('findlaw', 'lawyers.findlaw.com', 'findlaw');
  addSite('lawyersdotcom', 'lawyers.com', 'lawyersdotcom');
  addSite('superlawyers', 'superlawyers.com', 'superlawyers');
} else {
  addSite('trustpilot', 'trustpilot.com', 'trustpilot');
  addSite('glassdoor', 'glassdoor.com', 'glassdoor');
  addSite('angi', 'angi.com', 'angi');
  addSite('thumbtack', 'thumbtack.com', 'thumbtack');
  addSite('chamber', 'chamberofcommerce.com', 'chamber');
}

// === REVIEW PLATFORM SEARCHES ===
const reviewTarget = gbName || org || subject;
if (selected.has('gmb')) {
  queries.push({ engine: 'google', q: `"${reviewTarget}" reviews${market ? ' ' + market : ''}`, kind: 'reviews_gmb', num: 20 });
  if (org && reviewTarget !== org) {
    queries.push({ engine: 'google', q: `"${org}" reviews${market ? ' ' + market : ''}`, kind: 'reviews_org_gmb', num: 20 });
  }
}

if (selected.has('yelp')) {
  queries.push({ engine: 'google', q: `site:yelp.com "${reviewTarget}"${market ? ' ' + market : ''}`, kind: 'site_yelp', num: 10 });
}

if (selected.has('bbb')) {
  queries.push({ engine: 'google', q: `site:bbb.org "${org || subject}"`, kind: 'site_bbb', num: 10 });
}

// === SOCIAL MEDIA SEARCHES ===
if (selected.has('linkedin')) {
  const liPath = subjectType === 'attorney' ? 'linkedin.com/in' : 'linkedin.com';
  queries.push({ engine: 'google', q: `site:${liPath} "${subject}" ${keyword}`, kind: 'site_linkedin', num: 10 });
}

if (selected.has('facebook')) {
  queries.push({ engine: 'google', q: `site:facebook.com "${subject}" ${keyword}${market ? ' ' + market : ''}`, kind: 'site_facebook', num: 10 });
}

if (selected.has('x')) {
  queries.push({ engine: 'google', q: `site:x.com "${subject}" OR site:twitter.com "${subject}"`, kind: 'site_x', num: 10 });
}

if (selected.has('youtube')) {
  queries.push({ engine: 'google', q: `site:youtube.com "${subject}" ${keyword}`, kind: 'site_youtube', num: 10 });
}

// === NEWS SEARCHES (with date filtering) ===
if (selected.has('google_news')) {
  const tbs = `cdr:1,cd_min:${startDate.toLocaleDateString('en-US')},cd_max:${endDate.toLocaleDateString('en-US')}`;
  queries.push({ engine: 'google_news', q: `"${subject}"${market ? ' ' + market : ''}`, kind: 'news_subject', tbs });
  if (org) {
    queries.push({ engine: 'google_news', q: `"${org}"`, kind: 'news_org', tbs });
  }
}

// === COMPETITOR QUERIES ===
const competitors = splitList(item.competitors).slice(0, 5);
competitors.forEach((comp, idx) => {
  queries.push({ engine: 'google', q: `"${comp}" ${keyword}${market ? ' ' + market : ''}`, kind: `competitor_${idx + 1}_serp`, num: 20 });
  queries.push({ engine: 'google', q: `"${comp}" reviews${market ? ' ' + market : ''}`, kind: `competitor_${idx + 1}_reviews`, num: 10 });
});

// === BRAND CONSISTENCY SEARCH ===
queries.push({ engine: 'google_images', q: `"${subject}" ${keyword}${market ? ' ' + market : ''}`, kind: 'images_subject', num: 20 });

// Add metadata to each query
return queries.map(q => ({
  json: {
    ...item,
    query: q.q,
    engine: q.engine,
    kind: q.kind,
    num: q.num || 10,
    start: q.start || 0,
    tbs: q.tbs || null,
    competitors: competitors
  }
}));

// FIXED: Mode is now runOnceForAllItems
const items = $input.all();

// Helper functions
function pickOrganic(resp) {
  const r = resp || {};
  const organic = Array.isArray(r.organic_results) ? r.organic_results : [];
  return organic.map(o => ({
    position: o.position,
    title: o.title || '',
    link: o.link || '',
    displayed_link: o.displayed_link || '',
    snippet: o.snippet || '',
    date: o.date || null,
    rating: o.rating || null,
    reviews: o.reviews || null
  }));
}

function pickNews(resp) {
  const r = resp || {};
  const news = Array.isArray(r.news_results) ? r.news_results : [];
  return news.map(n => ({
    title: n.title || '',
    link: n.link || '',
    source: n.source?.name || n.source || '',
    date: n.date || '',
    snippet: n.snippet || '',
    thumbnail: n.thumbnail || null
  }));
}

function pickImages(resp) {
  const r = resp || {};
  const images = Array.isArray(r.images_results) ? r.images_results : [];
  return images.slice(0, 20).map(img => ({
    title: img.title || '',
    link: img.link || '',
    source: img.source || '',
    thumbnail: img.thumbnail || '',
    original: img.original || ''
  }));
}

function pickLocalResults(resp) {
  const r = resp || {};
  const local = Array.isArray(r.local_results) ? r.local_results : [];
  return local.map(l => ({
    title: l.title || '',
    rating: l.rating || null,
    reviews: l.reviews || null,
    address: l.address || '',
    phone: l.phone || '',
    website: l.website || '',
    type: l.type || ''
  }));
}

function pickKnowledgeGraph(resp) {
  const kg = resp?.knowledge_graph;
  if (!kg) return null;
  return {
    title: kg.title || '',
    type: kg.type || '',
    description: kg.description || '',
    website: kg.website || '',
    rating: kg.rating || null,
    reviews: kg.reviews || null,
    profiles: kg.profiles || []
  };
}

// Group results by kind
const grouped = {};
const allOrganic = [];
const allNews = [];
const allImages = [];
const allLocal = [];
let knowledgeGraph = null;

// First item for metadata extraction
let firstMeta = null;

for (const it of items) {
  const j = it.json;

  // After Merge by Position, data is combined into one object
  // The 'kind' field comes from the original query data
  const key = j.kind;

  // Store first item's metadata
  if (!firstMeta && j.subjectName) {
    firstMeta = j;
  }

  if (!key) {
    // If no 'kind', skip this item (shouldn't happen with proper merge)
    continue;
  }

  const organic = pickOrganic(j);
  const news = pickNews(j);
  const images = pickImages(j);
  const local = pickLocalResults(j);
  const kg = pickKnowledgeGraph(j);

  grouped[key] = {
    kind: key,
    engine: j.engine,
    query: j.query,
    organic: organic,
    news: news,
    images: images,
    local: local,
    knowledgeGraph: kg,
    totalResults: j.search_information?.total_results || 0
  };

  allOrganic.push(...organic.map(o => ({ ...o, source: key })));
  allNews.push(...news.map(n => ({ ...n, source: key })));
  allImages.push(...images.map(i => ({ ...i, source: key })));
  allLocal.push(...local.map(l => ({ ...l, source: key })));

  if (kg && !knowledgeGraph) {
    knowledgeGraph = kg;
  }
}

// Use firstMeta for report metadata, with fallbacks
const meta = firstMeta || items[0]?.json || {};

// Analyze search visibility
const attorneyName = meta.subjectName || '';
const firmName = meta.organizationName || '';

function countMentions(results, searchTerm) {
  if (!searchTerm) return 0;
  const term = searchTerm.toLowerCase();
  return results.filter(r => 
    (r.title?.toLowerCase().includes(term)) || 
    (r.snippet?.toLowerCase().includes(term))
  ).length;
}

function findRankings(results, searchTerm) {
  if (!searchTerm) return [];
  const term = searchTerm.toLowerCase();
  return results
    .filter(r => 
      (r.title?.toLowerCase().includes(term)) || 
      (r.link?.toLowerCase().includes(term.replace(/\s+/g, '')))
    )
    .map(r => r.position)
    .filter(p => p !== undefined);
}

// Calculate visibility metrics
const attorneyMentions = countMentions(allOrganic, attorneyName);
const firmMentions = firmName ? countMentions(allOrganic, firmName) : 0;
const serpOnlyResults = allOrganic.filter(o => String(o.source || '').startsWith('serp_'));
const attorneyRankings = findRankings(serpOnlyResults, attorneyName);

// Identify platform presence
const platformPresence = {
  avvo: allOrganic.some(r => r.link?.includes('avvo.com')),
  martindale: allOrganic.some(r => r.link?.includes('martindale.com')),
  justia: allOrganic.some(r => r.link?.includes('justia.com')),
  findlaw: allOrganic.some(r => r.link?.includes('findlaw.com')),
  superlawyers: allOrganic.some(r => r.link?.includes('superlawyers.com')),
  linkedin: allOrganic.some(r => r.link?.includes('linkedin.com')),
  yelp: allOrganic.some(r => r.link?.includes('yelp.com')),
  bbb: allOrganic.some(r => r.link?.includes('bbb.org')),
  facebook: allOrganic.some(r => r.link?.includes('facebook.com')),
  youtube: allOrganic.some(r => r.link?.includes('youtube.com'))
};

// Extract review signals from snippets
function extractReviewSignals(results) {
  const signals = [];
  for (const r of results) {
    const text = (r.snippet || '') + ' ' + (r.title || '');
    const ratingMatch = text.match(/(\d\.\d)\s*(?:out of|\/)\s*5|rated\s*(\d\.\d)|stars?\s*(\d\.\d)|(\d\.\d)\s*stars?/i);
    const reviewMatch = text.match(/(\d+)\s*(?:reviews?|ratings?)/i);

    if (ratingMatch || reviewMatch) {
      signals.push({
        source: r.link || '',
        rating: ratingMatch ? parseFloat(ratingMatch[1] || ratingMatch[2] || ratingMatch[3] || ratingMatch[4]) : null,
        reviewCount: reviewMatch ? parseInt(reviewMatch[1]) : null,
        snippet: r.snippet?.slice(0, 200)
      });
    }
  }
  return signals;
}

const reviewSignals = extractReviewSignals(allOrganic);

// Build analysis payload
const payload = {
  meta: {
    reportDate: meta.reportDate || new Date().toISOString().slice(0, 10),
    analysisMonths: meta.analysisMonths || 24,
    subjectName: meta.subjectName,
    subjectType: meta.subjectType,
    organizationName: meta.organizationName,
    category: meta.category,
    cityState: meta.cityState,
    website: meta.website,
    source: meta.source,
    spItemId: meta.spItemId,
    requestorEmail: meta.requestorEmail,
    ccEmail: meta.ccEmail,
    submittedAt: meta.submittedAt
  },
  inputs: {
    domains: meta.domains || [],
    competitors: meta.competitors || [],
    notes: meta.notes || ''
  },
  analysis: {
    totalQueriesRun: Object.keys(grouped).length,
    totalOrganicResults: allOrganic.length,
    totalNewsResults: allNews.length,
    attorneyMentions: attorneyMentions,
    firmMentions: firmMentions,
    topRankings: attorneyRankings.slice(0, 10),
    platformPresence: platformPresence,
    reviewSignals: reviewSignals,
    knowledgeGraph: knowledgeGraph
  },
  results: grouped,
  aggregated: {
    topOrganic: allOrganic.slice(0, 50),
    recentNews: allNews.slice(0, 20),
    images: allImages.slice(0, 15),
    localResults: allLocal
  }
};

return [{ json: payload }];

