// Validate and parse AI output
const input = $input.first().json;
let reportJson;

// Try to extract JSON from AI output
const aiOutput = input.output || input.text || input.message?.content || JSON.stringify(input);

try {
  // Remove potential markdown code fences
  let cleanJson = aiOutput
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  reportJson = JSON.parse(cleanJson);
} catch (parseError) {
  // Try to find JSON object in the response
  const jsonMatch = aiOutput.match(/\{[\s\S]*\}/m);
  if (jsonMatch) {
    try {
      reportJson = JSON.parse(jsonMatch[0]);
    } catch (e) {
      reportJson = null;
    }
  }
}

// Validation function
function validateReport(report) {
  const errors = [];

  if (!report) {
    errors.push('Failed to parse JSON from AI output');
    return { valid: false, errors };
  }

  if (!report.title_block) errors.push('Missing title_block');
  if (!report.overall_reputation_score) errors.push('Missing overall_reputation_score');
  if (!report.executive_summary) errors.push('Missing executive_summary');
  if (!Array.isArray(report.sections)) errors.push('Missing or invalid sections array');
  if (!report.recommendations) errors.push('Missing recommendations');

  return {
    valid: errors.length === 0,
    errors
  };
}

const validation = validateReport(reportJson);

if (!validation.valid) {
  // Create fallback report structure
  const meta = $('Aggregate Search Data').first().json.meta || {};
