// Escape HTML function
function esc(s) {
  return String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// Helper to render a table
function renderTable(headers, rows, options = {}) {
  const { striped = true, compact = false } = options;
  const cellPadding = compact ? '8px 10px' : '12px 14px';

  const headerHtml = headers.map(h => 
    `<th style="text-align:left;background:#f8f9fa;border-bottom:2px solid #dee2e6;padding:${cellPadding};font-size:13px;font-weight:700;color:#1a1a2e;">${esc(h)}</th>`
  ).join('');

  const bodyHtml = rows.map((row, idx) => {
    const bgColor = striped && idx % 2 === 1 ? '#fafbfc' : '#ffffff';
    const cells = row.map(cell => 
      `<td style="border-bottom:1px solid #eee;padding:${cellPadding};font-size:13px;color:#333333;vertical-align:top;background:${bgColor};">${esc(cell)}</td>`
    ).join('');
    return `<tr>${cells}</tr>`;
  }).join('');

  return `
    <table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="border:1px solid #dee2e6;border-radius:8px;border-collapse:separate;border-spacing:0;overflow:hidden;margin:16px 0;">
      <thead><tr>${headerHtml}</tr></thead>
      <tbody>${bodyHtml}</tbody>
    </table>`;
}

