function getScoreColor(scoreVal) {
  if (scoreVal === null || scoreVal === undefined) return '#6c757d';
  if (scoreVal >= 85) return '#28a745';
  if (scoreVal >= 70) return '#17a2b8';
  if (scoreVal >= 55) return '#ffc107';
  if (scoreVal >= 40) return '#fd7e14';
  return '#dc3545';
}

