return [{
  json: {
    html: html,
    reportJson: report,
    meta: meta,
    requestorEmail: meta.requestorEmail,
    ccEmail: meta.ccEmail,
    subjectName: meta.subjectName,
    subject: `Online Reputation Report — ${meta.subjectName || 'Subject'}`
  }
}];

const resp = $input.first().json;
const rows = Array.isArray(resp.value) ? resp.value : [];
const now = new Date();

function splitList(v) { return String(v || '').split(/[;\n]/).map(s => s.trim()).filter(Boolean); }
function lk(v) { return v && typeof v === 'object' ? (v.LookupValue || '') : String(v || ''); }

const out = [];
for (const row of rows) {
  const f = row.fields || {};
  if ((f.Status || 'Active') !== 'Active') continue;

  // Due-by-frequency logic
  const freq = f.Frequency || 'OneTime';
  const last = f.LastReportDate ? new Date(f.LastReportDate) : null;
  const days = last ? (now - last) / 86400000 : null;
  let due = false;
  if (freq === 'OneTime') due = !last;
  else if (freq === 'Monthly') due = !last || days >= 28;
  else if (freq === 'Quarterly') due = !last || days >= 89;
  if (!due) continue;

  // Recipients: ReportRecipients, falling back to CRM contact email (lookup projection)
  let recips = splitList(f.ReportRecipients);
  const crmEmail = lk(f['OrganizationName_x003a__x0020_Co']);
  if (!recips.length && crmEmail) recips = [crmEmail];
  if (!recips.length || !f.Title) continue; // fail-safe: skip rows we cannot deliver

  const city = lk(f['OrganizationName_x003a__x0020_Ci']);
  const state = lk(f['OrganizationName_x003a__x0020_St']);

  out.push({ json: {
    requestorEmail: recips.join(','),
    requestorName: lk(f['OrganizationName_x003a__x0020_Pr']),
    subjectName: f.Title,
    subjectType: String(f.SubjectType || 'Attorney').toLowerCase(),
    organizationName: lk(f.OrganizationName),
    category: f.Category || '',
    cityState: [city, state].filter(Boolean).join(', '),
    website: lk(f['OrganizationName_x003a__x0020_Do']),
    aliases: splitList(f.Aliases),
    socialProfiles: splitList(f.SocialProfiles),
    googleBusinessName: f.GoogleBusinessName || '',
    notes: f.Notes || '',
    submittedAt: now.toISOString(),
    analysisMonths: Number(f.AnalysisMonths || 24),
    domains: splitList(f.DirectoriesToCheck).map(s => s.toLowerCase()),
    competitors: splitList(f.Competitors),
    reportDate: now.toISOString().slice(0, 10),
    ccEmail: splitList(f.CCEmails).join(',') || 'user@example.com',
    source: 'crm',
    spItemId: String(row.id)
  }});
}
return out;
